-- Service: collab  (per cell)
-- GENERATED by tools/split.py from plan/db/*.sql. Edit the source files or split.py, then re-run.
-- Load order: _prelude.sql, collab.sql, collab.later.sql, _epilogue.sql
CREATE TABLE scheduled_comments (                    -- ASSUMED ('Schedule for later'; PROVEN only the search request)
  id uuid PRIMARY KEY,
  workspace_id uuid NOT NULL /* id -> access.workspaces */,
  parent_type text NOT NULL CHECK (parent_type IN ('task','doc','page','list','goal','view')),
  parent_id uuid NOT NULL,
  author_id uuid NOT NULL /* id -> identity.users */,
  body jsonb NOT NULL,
  send_at timestamptz NOT NULL,
  status text NOT NULL DEFAULT 'scheduled' CHECK (status IN ('scheduled','sent','cancelled','failed')),
  sent_comment_id uuid REFERENCES comments(id),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  version integer NOT NULL DEFAULT 1
);

-- sender worker scan; global by design (workers are not tenant scoped), tiny partial index.
CREATE INDEX scheduled_comments_due ON scheduled_comments (send_at) WHERE status = 'scheduled';

CREATE INDEX scheduled_comments_author ON scheduled_comments (workspace_id, author_id, send_at) WHERE status = 'scheduled';

-- approvals: PROVEN only an approvals-count request; timesheet approvals stay in timesheet_approvals (notes: open question).
CREATE TABLE approvals (
  id uuid PRIMARY KEY,
  workspace_id uuid NOT NULL /* id -> access.workspaces */,
  subject_type text NOT NULL CHECK (subject_type IN ('task','doc','page','goal')),   -- ASSUMED
  subject_id uuid NOT NULL,
  title text,
  requested_by uuid NOT NULL /* id -> identity.users */,
  mode text NOT NULL DEFAULT 'any' CHECK (mode IN ('any','all')),
  status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','approved','rejected','cancelled')),
  decided_at timestamptz,
  deleted_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  version integer NOT NULL DEFAULT 1
);

CREATE INDEX approvals_subject ON approvals (workspace_id, subject_type, subject_id);

-- approvals on a task
CREATE TABLE approval_reviewers (
  approval_id uuid NOT NULL REFERENCES approvals(id) ON DELETE CASCADE,
  user_id uuid NOT NULL /* id -> identity.users */,
  workspace_id uuid NOT NULL /* id -> access.workspaces */,
  decision text NOT NULL DEFAULT 'pending' CHECK (decision IN ('pending','approved','rejected')),
  comment text,
  decided_at timestamptz,
  PRIMARY KEY (approval_id, user_id)
);

CREATE INDEX approval_reviewers_user ON approval_reviewers (workspace_id, user_id) WHERE decision = 'pending';

ALTER TABLE approval_reviewers ADD COLUMN step_no smallint NOT NULL DEFAULT 1;
